'use client';

import { useActionState } from 'react';

async function submitContactMessage(prevState: FormState | null, formData: FormData) {
  'use server';

  const name = formData.get('name') as string;
  const email = formData.get('email') as string;
  const message = formData.get('message') as string;

  // Validation: check that all fields are provided
  if (!name || typeof name !== 'string' || name.trim() === '') {
    return { success: false, error: 'Name is required.' };
  }
  if (!email || typeof email !== 'string' || email.trim() === '') {
    return { success: false, error: 'Email is required.' };
  }
  if (!message || typeof message !== 'string' || message.trim() === '') {
    return { success: false, error: 'Message is required.' };
  }

  // Simulate saving the contact message
  console.log('Contact message received:', { name: name.trim(), email: email.trim(), message: message.trim() });

  return { success: true, error: null };
}

type FormState = { success: boolean; error: string | null };

export default function ContactForm() {
  const [state, formAction] = useActionState(submitContactMessage, null);

  return (
    <div>
      <h2>Contact Us</h2>
      <form action={formAction}>
        <div>
          <label htmlFor="name">Name</label>
          <input id="name" name="name" type="text" placeholder="Your name" required />
        </div>
        <div>
          <label htmlFor="email">Email</label>
          <input id="email" name="email" type="email" placeholder="your@email.com" required />
        </div>
        <div>
          <label htmlFor="message">Message</label>
          <textarea id="message" name="message" placeholder="Your message" rows={5} required />
        </div>
        {state?.error && (
          <p style={{ color: 'red' }}>{state.error}</p>
        )}
        {state?.success && (
          <p style={{ color: 'green' }}>Thank you! Your message has been submitted.</p>
        )}
        <button type="submit">Send Message</button>
      </form>
    </div>
  );
}

